"""Inspect the local workspace: list files and describe any SQLite databases."""

import os
import sqlite3

CWD = os.getcwd()
print("Current working directory:", CWD)
print("Files in workspace root:")
for name in sorted(os.listdir(CWD)):
    full = os.path.join(CWD, name)
    kind = "dir" if os.path.isdir(full) else "file"
    size = os.path.getsize(full) if os.path.isfile(full) else "-"
    print(f"  [{kind}] {name}  ({size} bytes)")

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3", ".db3")

for name in sorted(os.listdir(CWD)):
    full = os.path.join(CWD, name)
    if not os.path.isfile(full):
        continue
    lower = name.lower()
    if lower.endswith(DB_EXTENSIONS):
        print(f"\n=== SQLite database: {name} ===")
        try:
            with sqlite3.connect(full) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                cur.execute("SELECT type, name, sql FROM sqlite_master ORDER BY type, name")
                rows = cur.fetchall()
                if not rows:
                    print("  (database appears empty)")
                for row in rows:
                    print(f"  [{row['type']}] {row['name']}")
                    if row["sql"]:
                        print("      SQL:", row["sql"])
                for row in rows:
                    if row["type"] == "table" and not row["name"].startswith("sqlite_"):
                        cur.execute(f'PRAGMA table_info("{row["name"]}")')
                        cols = cur.fetchall()
                        print(f"  Columns of {row['name']}:")
                        for c in cols:
                            print(f"    - {c['name']} {c['type']} notnull={c['notnull']} default={c['dflt_value']!r} pk={c['pk']}")
        except sqlite3.Error as exc:
            print("  ERROR reading database:", exc)

"""Locate the SQLite database in this folder and report its schema.

Read-only helper: it never writes to or modifies any database.
"""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))
DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3", ".sql3")


def find_databases(folder):
    matches = []
    for name in sorted(os.listdir(folder)):
        full = os.path.join(folder, name)
        if os.path.isfile(full) and name.lower().endswith(DB_EXTENSIONS):
            matches.append(full)
    return matches


def describe_database(db_path):
    print("DATABASE:", db_path)
    with sqlite3.connect(db_path) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        objects = cur.execute(
            "SELECT name, type FROM sqlite_master "
            "WHERE type IN ('table', 'view') ORDER BY name"
        ).fetchall()
        if not objects:
            print("  (no tables or views)")
        for obj in objects:
            kind, name = obj["type"], obj["name"]
            print("  %s: %s" % (kind.upper(), name))
            for col in cur.execute("PRAGMA table_info(%s)" % name).fetchall():
                flags = []
                if col["notnull"]:
                    flags.append("NOT NULL")
                if col["pk"]:
                    flags.append("PK")
                dflt = col["dflt_value"]
                if dflt is not None:
                    flags.append("DEFAULT %r" % dflt)
                print("      col: %s %s %s" % (col["name"], col["type"], " ".join(flags)))
            try:
                row = cur.execute("SELECT * FROM %s LIMIT 1" % name).fetchone()
                print("      sample row:", dict(row) if row is not None else None)
            except Exception as exc:  # pragma: no cover - defensive
                print("      (could not sample row: %s)" % exc)


def main():
    print("Folder:", HERE)
    print("Entries:")
    for name in sorted(os.listdir(HERE)):
        print("  -", name)
    databases = find_databases(HERE)
    if not databases:
        print("NO_DATABASE_FOUND")
        return
    for db in databases:
        try:
            describe_database(db)
        except Exception as exc:
            print("ERROR reading %s: %s" % (db, exc))


if __name__ == "__main__":
    main()

